script:
card({
  name: 'Scoreboard',
  icon: 'trophy',
  permissions: [],
});

// Built once, used for each team in the view: Score({ team, points }).
components.Score = {
  about: 'A team, its points, and buttons to change them',
  props: { team: '', points: 0, tone: 'accent' },
  view: (props) => column([
    text(props.team, { bold: true, align: 'center' }),
    text(String(props.points), { size: 'huge', tone: props.tone, align: 'center' }),
    row([
      button('−1', 'add', { team: props.team, by: -1 }),
      button('+1', 'add', { team: props.team, by: 1 }, { tone: props.tone }),
    ]),
  ]),
};

// A title over whatever goes inside it: Panel({ title }, ...children).
components.Panel = {
  about: 'A title over the components inside it',
  props: { title: '' },
  view: (props, children) => column([text(props.title, { tone: 'muted', align: 'center' }), ...children, divider()]),
};

on.add = (state, args, ctx) => {
  if (state.points[args.team] === undefined) throw 'No such team';
  state.points[args.team] = Math.max(0, state.points[args.team] + args.by);
};

on.reset = (state, args, ctx) => {
  for (const team of Object.keys(state.points)) {
    state.points[team] = 0;
  }
};

function init(ctx) {
  return { points: { Home: 0, Away: 0 } };
}

function view(state, me, now, local) {
  return column([
    Panel({ title: 'Scoreboard' }, row([
      Score({ team: 'Home', points: state.points.Home }),
      Score({ team: 'Away', points: state.points.Away, tone: 'warning' }),
    ])),
    button('Start again', 'reset', null, { tone: 'muted' }),
  ]);
}

function pause(local, ctx) {
  // Runs on this phone when the card leaves the screen.
}

function resume(local, ctx) {
  // Runs on this phone when it comes back.
}
